Hier ist eine C++ Funktion, die auf einen `std::string` mit Markdown-formatiertem Text verweist und einen `std::string` mit HTML-formatiertem Text zurückgibt:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Define Markdown to HTML conversion rules
const std::unordered_map<std::string, std::string> markdown_to_html {
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"`", "<code>"},
    {"**", "<strong>"},
    {"__", "<strong>"},
    {"* ", "<em>"},
    {"[", "<a href='"],
    {"](", ")</a>"},
    {"http://", "<a href='"},
    {"https://", "<a href='"},
    {"```\n", "<pre><code>"}, // multi-line code block
    {"```\n", "</code></pre>"}, // multi-line code block
    {"```", "<code>"}, // single-line code block
    {"```", "</code>"}, // single-line code block
    {"---\n", "<hr>"}, // horizontal rule
    {"***\n", "<hr>"}, // horizontal rule
    {"(\*\n)*\n", "<p>"}, // paragraph
    {"}\n", "</p>"}, // paragraph
    {",\n", "<br>"}, // comma-separated list
    {"\n", "<br>"}, // line break
    {"\\[([^]]+)\\]\\([^)]+\\)", "<a href=\"\\2\">\\1</a>"}, // image tag
    {"\\[([^]]+)\\]", "<img src=\"\\1\">"} // image tag (without URL)
};

// Convert Markdown to HTML
std::string markdown_to_html(const std::string& markdown) {
    std::string html;

    // Replace all Markdown patterns with their corresponding HTML
    for (const auto& [pattern, replacement] : markdown_to_html) {
        std::regex re(pattern);
        html = std::regex_replace(html, re, replacement);
    }

    return html;
}

int main() {
    std::string markdown = "## Heading\n\nThis is a paragraph.\n\n* List item 1\n* List item 2\n\n![Image](https://example.com/image.jpg)";

    std::string html = markdown_to_html(markdown);

    std::cout << html << std::endl;

    return 0;
}
```

Die Funktion `markdown_to_html` nimmt einen `std::string` mit Markdown-Formatierung als Eingabe und gibt den entsprechenden HTML-Code als `std::string` zurück.

Die `markdown_to_html`-Konstante definiert die Regeln für die Markdown-Zu-HTML-Konvertierung, die in einer `unordered_map` gespeichert werden. Die Schlüssel sind die Markdown-Pattern und die Werte sind die entsprechenden HTML-Tags oder -Texte.

Die Funktion `std::regex_replace` wird benutzt, um jedes Markdown-Pattern mit dem entsprechenden HTML-Text zu ersetzen. 

